// The "H" from the start of the Logo path, as used for the favicon.
export const H_PATH =
	"M0 110.74l43.7-33.63V186h56V33.66L143.5 0v344.75l-43.76 33.66v-151.6h-56v195.05L0 455.48z";
export const H_WIDTH = 143.5;
export const H_HEIGHT = 455.48;

// Hue for the static fallback icons (favicon.ico, PNGs) generated by scripts/generate-icons.ts.
export const STATIC_ICON_HUE = 80;

// Lightness/chroma pairs matching the --piko-palette-dynamic-* steps.
export const PALETTE = {
	1: { l: 97.2, c: 0.014, cP3: 0.039 },
	4: { l: 84.6, c: 0.105, cP3: 0.163 },
	7: { l: 54.5, c: 0.182, cP3: 0.241 },
} as const;

function oklchToLinearSrgb(l: number, c: number, h: number) {
	const hRad = (h * Math.PI) / 180;
	const a = c * Math.cos(hRad);
	const b = c * Math.sin(hRad);

	const lCone = (l + 0.3963377774 * a + 0.2158037573 * b) ** 3;
	const mCone = (l - 0.1055613458 * a - 0.0638541728 * b) ** 3;
	const sCone = (l - 0.0894841775 * a - 1.291485548 * b) ** 3;

	return [
		4.0767416621 * lCone - 3.3077115913 * mCone + 0.2309699292 * sCone,
		-1.2684380046 * lCone + 2.6097574011 * mCone - 0.3413193965 * sCone,
		-0.0041960863 * lCone - 0.7034186147 * mCone + 1.707614701 * sCone,
	];
}

function isInSrgbGamut(channels: number[]) {
	return channels.every((channel) => channel >= -1e-4 && channel <= 1 + 1e-4);
}

// Converts an OKLCH colour to sRGB hex, reducing chroma until it fits the gamut.
export function oklchToHex(l: number, c: number, h: number): string {
	let low = 0;
	let high = c;
	let channels = oklchToLinearSrgb(l, c, h);

	if (!isInSrgbGamut(channels)) {
		for (let step = 0; step < 24; step += 1) {
			const mid = (low + high) / 2;
			if (isInSrgbGamut(oklchToLinearSrgb(l, mid, h))) {
				low = mid;
			} else {
				high = mid;
			}
		}
		channels = oklchToLinearSrgb(l, low, h);
	}

	return `#${channels
		.map((linear) => {
			const clamped = Math.min(1, Math.max(0, linear));
			const encoded =
				clamped <= 0.0031308
					? 12.92 * clamped
					: 1.055 * clamped ** (1 / 2.4) - 0.055;
			return Math.round(encoded * 255)
				.toString(16)
				.padStart(2, "0");
		})
		.join("")}`;
}

function oklch(step: keyof typeof PALETTE, hue: number, p3 = false) {
	const { l, c, cP3 } = PALETTE[step];
	return `oklch(${l}% ${p3 ? cP3 : c} ${hue})`;
}

export function paletteHex(step: keyof typeof PALETTE, hue: number) {
	const { l, c } = PALETTE[step];
	return oklchToHex(l / 100, c, hue);
}

// A square viewBox around the H. `padding` is a fraction of the side length.
export function hViewBox(padding = 0) {
	const side = H_HEIGHT / (1 - padding * 2);
	return `${-(side - H_WIDTH) / 2} ${-(side - H_HEIGHT) / 2} ${side} ${side}`;
}

// Favicon SVG in the link colour for `hue`, following the browser's light/dark scheme.
export function faviconSvg(hue: number): string {
	return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${hViewBox()}">
	<style>
		path { fill: ${paletteHex(7, hue)}; fill: ${oklch(7, hue)}; }
		@media (color-gamut: p3) {
			path { fill: ${oklch(7, hue, true)}; }
		}
		@media (prefers-color-scheme: dark) {
			path { fill: ${paletteHex(4, hue)}; fill: ${oklch(4, hue)}; }
		}
		@media (prefers-color-scheme: dark) and (color-gamut: p3) {
			path { fill: ${oklch(4, hue, true)}; }
		}
	</style>
	<path d="${H_PATH}" />
</svg>
`;
}
